<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {ops} from '../../api/operations'
const props=defineProps<{draftId:string}>()
const rows=ref<any[]>([]),notes=ref<Record<string,string>>({}),loading=ref(false),busy=ref(false),error=ref('')
const routes:Record<string,string>={rule:'规则核对',agent:'Agent 改进',training:'人员培训'}
const tags:Record<string,string>={evidence:'证据',dose:'剂量',nutrition:'营养',scope:'权限',format:'格式',workflow:'流程',other:'其他'}
let generation=0
async function load(){const current=++generation;rows.value=[];loading.value=true;error.value='';try{const data=await ops.get(`drafts/${props.draftId}/feedback`);if(current===generation)rows.value=data.items}catch(e){if(current===generation)error.value=e instanceof Error?e.message:'修正记录读取失败'}finally{if(current===generation)loading.value=false}}
async function resolve(id:string){if(busy.value||!notes.value[id]?.trim())return;const current=generation;busy.value=true;error.value='';try{const data=await ops.post(`feedback/${id}/resolve`,{note:notes.value[id].trim()});if(current===generation){rows.value=data.items;notes.value[id]=''}}catch(e){if(current===generation)error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
watch(()=>props.draftId,()=>{notes.value={};void load()},{immediate:true})
onBeforeUnmount(()=>generation++)
</script>
<template><section class="draft-feedback" aria-label="人工修正与复盘"><h3>人工修正与复盘</h3><p v-if="loading" role="status">正在读取修正记录…</p><p v-if="error" class="feedback-error" role="alert">{{ error }} <button class="btn" :disabled="busy||loading" @click="load">重试</button></p><p v-if="!loading&&!error&&!rows.length" class="feedback-help">尚无人工修正；修改草稿并填写原因后，可在这里跟进复盘。</p><article v-for="item in rows" :key="item.id"><header><b>{{ routes[item.route] }} · {{ tags[item.tag]||item.tag }}</b><span>{{ item.closed?'已闭环':'待复盘' }}</span></header><p>{{ item.reason }}</p><details v-if="Object.keys(item.before).length"><summary>查看修改前后内容</summary><h4>修改前</h4><pre>{{ JSON.stringify(item.before,null,2) }}</pre><h4>修改后</h4><pre>{{ JSON.stringify(item.after,null,2) }}</pre></details><details v-if="item.validation_snapshot"><summary>查看修改前后校验版本</summary><p>草稿第 {{ item.validation_snapshot.previous_version }} → {{ item.validation_snapshot.version }} 版</p><p>规则：{{ item.validation_snapshot.before.rule_version }} → {{ item.validation_snapshot.after.rule_version }}</p><p>风险：{{ item.validation_snapshot.before.risk }} → {{ item.validation_snapshot.after.risk }} 级</p><p class="feedback-help">图事实指纹：{{ item.validation_snapshot.after.graph_hash }}</p></details><p v-if="item.resolution_note">复盘结论：{{ item.resolution_note }}</p><p v-if="item.closed" class="feedback-help">{{ item.resolved_at?'已记录复盘结论':'历史记录已标记闭环' }}</p><form v-if="item.can_resolve" @submit.prevent="resolve(item.id)"><label :for="`feedback-${item.id}`">复盘结论<textarea :id="`feedback-${item.id}`" v-model="notes[item.id]" class="input" rows="3" maxlength="1000" required :disabled="busy" placeholder="记录核对依据、采取的措施与验证结果"/></label><button class="btn" :disabled="busy||!notes[item.id]?.trim()">{{ busy?'保存中…':'保存结论并闭环' }}</button></form></article></section></template>
<style scoped>.draft-feedback{border-top:1px solid var(--line);margin-top:24px;padding-top:8px}.draft-feedback h3{font-size:16px}.draft-feedback article{border:1px solid var(--line);border-radius:10px;padding:16px;margin:14px 0;overflow-wrap:anywhere}.draft-feedback header{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.draft-feedback p{line-height:1.8;white-space:pre-wrap}.feedback-help{color:var(--muted)}.feedback-error{color:#a32f2f}.draft-feedback label{display:grid;gap:8px;margin:14px 0}.draft-feedback pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--bg);padding:12px;border-radius:8px}.draft-feedback summary{cursor:pointer;min-height:44px;display:flex;align-items:center}.draft-feedback .btn{min-height:44px}.draft-feedback :focus-visible{outline:2px solid var(--brand);outline-offset:3px}</style>
